        // to keep other bins empty for larger future items.
        let tightness_penalty = (mean_residual - post).powi(2) * 0.5;
        score += tightness_penalty;

        // If next_item_size is large, avoid bins that would make it impossible to fit 
        // the next item (post_residual < next_item_size).
