    // Penalty for opening a new bin:
    // We scale the penalty by progress to be more conservative early on, 
    // but become more aggressive in opening new bins as the stream nears the end.
    if bin_residual == bin_capacity {
        score = 1000.0 * (1.0 - (progress * 0.5));
    } else {
        // Lookahead interaction: 
